import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"ユーザーガイド","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/index.md","filePath":"ja-JP/user-guide/index.md","lastUpdated":1787586465000}'),s={name:"ja-JP/user-guide/index.md"};function l(i,t,n,d,c,g){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="ユーザーガイド" tabindex="-1">ユーザーガイド <a class="header-anchor" href="#ユーザーガイド" aria-label="Permalink to &quot;ユーザーガイド&quot;">​</a></h1><p>Lertaro 公式ユーザーガイドへようこそ！Lertaro は、Windows 向けに高度に最適化された超高速ファイル検索＆生産性向上ランチャーです。バックグラウンドでインメモリインデックスツリー（NTFS / ReFS は USN 変更ジャーナル、その他のファイルシステムはリアルタイムイベント監視）を常時保持し、数千万件規模のファイルに対してもミリ秒未満の検索応答を実現します。</p><p>本ガイドでは、日々の作業に必要な基本操作から高度な機能まで体系的に解説します。</p><ul><li><strong><a href="./getting-started.html">クイックスタート</a></strong> —— インストール手順、ポータブル版、アーキテクチャ概要、3 つのウィンドウ形態（クイック / メイン / インライン）、基本操作。</li><li><strong><a href="./search-syntax.html">検索構文</a></strong> —— あいまい一致、修飾演算子（<code>!</code> 除外、<code>&#39;</code> 完全一致、<code>^</code> 前方一致、<code>$</code> 後方一致、<code>|</code> OR 条件）、ドライブ指定、パスモード、多言語ピンイン対応。</li><li><strong><a href="./hotkeys.html">ホットキーとマウス操作</a></strong> —— グローバルホットキー一覧、検索ボックスロゴのマウス操作、クイックナビゲーション階層メニュー、固定キー。</li><li><strong><a href="./actions-and-preview.html">アクションとプレビュー</a></strong> —— コンテキストアクションメニュー（<code>Ctrl+O</code>）、メインウィンドウ一覧操作、QuickLook メディア/文書プレビュー、対話型プラグインカード。</li><li><strong><a href="./space-analyzer.html">ストレージ分析</a></strong> —— ディスク I/O ゼロの超高速ツリーマップ＆サイズ降順一覧で大容量ファイルを素早く特定。</li><li><strong><a href="./instant-answers.html">インスタント機能とキーワード拡張</a></strong> —— 常時利用可能な計算機・環境変数・コマンド実行、およびプロセス管理（<code>ps</code>）、ウィンドウ切り替え（<code>win</code>）、ブラウザーデータ（<code>bm</code>）、設定検索（<code>set</code>）などのプラグイン。</li><li><strong><a href="./cli.html">コマンドライン検索（lff）</a></strong> —— ターミナル用対話型あいまい検索ツール。インメモリインデックスを共有し、パイプラインやシェルスクリプトと連携。</li><li><strong><a href="./uri-protocol.html">URI プロトコル（lertaro://）</a></strong> —— ブラウザーリンクやショートカット、スクリプトから検索画面、設定画面、LocalSend 送信へダイレクトジャンプ。</li><li><strong><a href="./file-manager-support.html">対応ファイルマネージャー</a></strong> —— Windows 標準ダイアログや Directory Opus、Total Commander、XYplorer、Files などのファイラーとの統合。</li><li><strong><a href="./settings/">設定項目リファレンス</a></strong> —— サービス状態、インデックス管理、一般設定、外観、ホットキー、プラグイン設定の全項目解説。</li><li><strong><a href="./troubleshooting.html">トラブルシューティング</a></strong> —— ホットキーが反応しない場合やインデックス未更新時の診断とログ確認手順。</li><li><strong><a href="./donate.html">寄付とサポート</a></strong> —— Lertaro の継続的な開発とオープンソース活動への支援。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>初めて Lertaro をご利用になる方は、まず <a href="./getting-started.html"><strong>クイックスタート</strong></a> からご覧ください。</p></div>',5)])])}const m=e(s,[["render",l]]);export{p as __pageData,m as default};
